import sys, concurrent.futures, requests

base = "http://web.chal.csaw.io:3000"
wordlist = sys.argv[1] if len(sys.argv) > 1 else "common.txt"
exts = ["", ".html", ".txt", ".js", ".json", ".php", ".bak", ".md", ".note"]

words = []
with open(wordlist, errors="ignore") as f:
    for line in f:
        line = line.strip()
        if line and not line.startswith("#"):
            words.append(line)

urls = []
for w in words:
    for e in exts:
        urls.append("/" + w + e)

s = requests.Session()
s.headers["User-Agent"] = "Mozilla/5.0"

def check(u):
    try:
        r = s.get(base + u, timeout=8, allow_redirects=False)
        if r.status_code not in (404,):
            return (u, r.status_code, len(r.content))
    except Exception:
        return None

with concurrent.futures.ThreadPoolExecutor(max_workers=40) as ex:
    for res in ex.map(check, urls):
        if res:
            print(res, flush=True)

